AUTO = ROOT / "automation"
FILES = {'contracts.py': 'from __future__ import annotations\nfrom dataclasses import dataclass\n\n@dataclass(frozen=True)\nclass StageContract:\n    stage_id: str\n    title: str\n    script: str | None = None\n    requires: tuple[str, ...] = ()\n    produces: tuple[str, ...] = ()\n    dependencies: tuple[str, ...] = ()\n    network_access: bool = False\n    science_pixels_read: bool = False\n    non_science_pixels_read: bool = False\n    transient_detector_rerun: bool = False\n    candidate_state_mutation: bool = False\n    retryable: bool = False\n    notes: str = ""\n\n    @property\n    def safe_default(self) -> bool:\n        return (\n            not self.network_access\n            and not self.transient_detector_rerun\n            and not self.candidate_state_mutation\n        )\n', 'state_store.py': 'from __future__ import annotations\nimport json\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\ndef utc_now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\nclass StateStore:\n    def __init__(self, root: Path):\n        self.root = root\n        self.root.mkdir(parents=True, exist_ok=True)\n        self.events_path = self.root / "events.jsonl"\n        self.snapshot_path = self.root / "snapshot.json"\n\n    def append(self, event_type: str, payload: dict[str, Any]) -> dict[str, Any]:\n        event = {"timestamp_utc": utc_now(), "event_type": event_type, "payload": payload}\n        with self.events_path.open("a", encoding="utf-8") as fh:\n            fh.write(json.dumps(event, sort_keys=True, default=str) + "\\n")\n        return event\n\n    def write_snapshot(self, obj: dict[str, Any]) -> None:\n        tmp = self.snapshot_path.with_suffix(".json.tmp")\n        tmp.write_text(json.dumps(obj, indent=2, sort_keys=True, default=str) + "\\n", encoding="utf-8")\n        tmp.replace(self.snapshot_path)\n', 'registry_order01.py': 'from __future__ import annotations\nfrom .contracts import StageContract\n\nORDER01_STAGES = [\n    StageContract(\n        stage_id="order01_closure_v028ag",\n        title="Final POSS endpoint disposition + two-observatory closure",\n        produces=("results/order01_native_full_v028/order01_candidate24_final_disposition_and_closure_v028ag.json",),\n        notes="Frozen authoritative closure artifact.",\n    ),\n    StageContract(\n        stage_id="dasch_exact_platephot_v028ao",\n        title="Exact raw DASCH platephot audit",\n        script="tools/audit_order01_dasch_exact_raw_platephot_v028ao.py",\n        produces=("results/order01_native_full_v028/order01_dasch_exact_raw_platephot_audit_v028ao.json",),\n    ),\n    StageContract(\n        stage_id="dasch_query_provenance_v028aq",\n        title="v028r platephot request provenance",\n        script="tools/audit_order01_dasch_v028r_source_request_v028aq.py",\n        produces=("results/order01_native_full_v028/order01_dasch_v028r_source_request_audit_v028aq.json",),\n    ),\n    StageContract(\n        stage_id="dasch_physical_morphology_v028ar_r1",\n        title="DASCH physical morphology",\n        script="tools/audit_order01_dasch_physical_morphology_v028ar_r1.py",\n        requires=("results/order01_native_full_v028/order01_dasch_exact_raw_platephot_audit_v028ao.json",),\n        produces=("results/order01_native_full_v028/order01_dasch_physical_morphology_v028ar_r1.json",),\n        science_pixels_read=True,\n    ),\n    StageContract(\n        stage_id="dasch_stellar_shape_v028as",\n        title="Amplitude-normalized stellar-shape audit",\n        script="tools/audit_order01_dasch_stellar_shape_v028as.py",\n        requires=("results/order01_native_full_v028/order01_dasch_physical_morphology_v028ar_r1.json",),\n        produces=("results/order01_native_full_v028/order01_dasch_stellar_shape_v028as.json",),\n        dependencies=("dasch_physical_morphology_v028ar_r1",),\n    ),\n    StageContract(\n        stage_id="dasch_flag_provenance_v028au",\n        title="Exact historical-hit flag provenance",\n        script="tools/audit_order01_dasch_v028i_exact_source_provenance_v028au.py",\n        produces=("results/order01_native_full_v028/order01_dasch_v028i_exact_source_provenance_v028au.json",),\n    ),\n    StageContract(\n        stage_id="dasch_recurrence_reclass_v028av",\n        title="Historical recurrence reclassification",\n        script="tools/audit_order01_dasch_historical_recurrence_v028av.py",\n        requires=("results/order01_native_full_v028/order01_dasch_stellar_shape_v028as.json",),\n        produces=("results/order01_native_full_v028/order01_dasch_historical_recurrence_reclassification_v028av.json",),\n        dependencies=("dasch_stellar_shape_v028as", "dasch_flag_provenance_v028au"),\n    ),\n    StageContract(\n        stage_id="dasch_local_prevalence_v028aw",\n        title="Local uncatalogued stellar-like prevalence",\n        script="tools/audit_order01_dasch_local_uncatalogued_stellar_prevalence_v028aw.py",\n        requires=(\n            "results/order01_native_full_v028/order01_dasch_stellar_shape_v028as.json",\n            "results/order01_native_full_v028/order01_dasch_physical_morphology_v028ar_r1.json",\n        ),\n        produces=("results/order01_native_full_v028/order01_dasch_local_uncatalogued_stellar_prevalence_v028aw.json",),\n        non_science_pixels_read=True,\n        dependencies=("dasch_stellar_shape_v028as",),\n    ),\n]\n\ndef by_id():\n    return {s.stage_id: s for s in ORDER01_STAGES}\n', 'baseline_order01_v001.json': '{\n  "baseline_id": "ORDER01_FROZEN_BASELINE_V001",\n  "description": "Current authoritative Order01 state after v028aw.",\n  "checks": [\n    {\n      "id": "two_observatory_closed",\n      "file": "results/order01_native_full_v028/order01_candidate24_final_disposition_and_closure_v028ag.json",\n      "type": "equals",\n      "path": "new_active_unresolved_two_observatory_set",\n      "expected": []\n    },\n    {\n      "id": "dasch_morphology_pixels_read",\n      "file": "results/order01_native_full_v028/order01_dasch_physical_morphology_v028ar_r1.json",\n      "type": "equals",\n      "path": "guards.science_pixels_read",\n      "expected": true\n    },\n    {\n      "id": "dasch_morphology_no_state_mutation",\n      "file": "results/order01_native_full_v028/order01_dasch_physical_morphology_v028ar_r1.json",\n      "type": "equals",\n      "path": "guards.candidate_state_mutation",\n      "expected": false\n    },\n    {\n      "id": "all_six_stellar_shape_consistent",\n      "file": "results/order01_native_full_v028/order01_dasch_stellar_shape_v028as.json",\n      "type": "all_field_equals",\n      "list_path": "summaries",\n      "field": "shape_classification",\n      "expected": "CONSISTENT_WITH_OFFICIAL_SOURCE_SHAPE_CLOUD",\n      "expected_count": 6\n    },\n    {\n      "id": "no_accepted_historical_recurrence",\n      "file": "results/order01_native_full_v028/order01_dasch_historical_recurrence_reclassification_v028av.json",\n      "type": "equals",\n      "path": "accepted_historical_recurrence_ranks",\n      "expected": []\n    },\n    {\n      "id": "local_prevalence_control_count",\n      "file": "results/order01_native_full_v028/order01_dasch_local_uncatalogued_stellar_prevalence_v028aw.json",\n      "type": "equals",\n      "path": "summary.usable_pixel_controls",\n      "expected": 3\n    },\n    {\n      "id": "local_prevalence_same_phenotype_count",\n      "file": "results/order01_native_full_v028/order01_dasch_local_uncatalogued_stellar_prevalence_v028aw.json",\n      "type": "equals",\n      "path": "summary.uncatalogued_stellar_like_controls",\n      "expected": 2\n    }\n  ],\n  "authoritative_interpretation": {\n    "order01_two_observatory_active_pairs": 0,\n    "preserved_dasch_single_plate_ranks": [\n      10,\n      24,\n      25,\n      26,\n      29,\n      30\n    ],\n    "accepted_historical_recurrence_ranks": [],\n    "dasch_single_plate_status": "UNRESOLVED_STELLAR_LIKE_SINGLE_PLATE_FEATURES",\n    "local_prevalence_status": "INSUFFICIENT_SAMPLE_FOR_RATE_ESTIMATE"\n  }\n}', 'runner.py': 'from __future__ import annotations\nimport argparse, json, subprocess, sys\nfrom pathlib import Path\nfrom typing import Any\n\nfrom .registry_order01 import ORDER01_STAGES, by_id\nfrom .state_store import StateStore\n\nROOT = Path(__file__).resolve().parents[1]\nAUTO = ROOT / "automation"\nSTATE = StateStore(AUTO / "state")\nBASELINE = AUTO / "baseline_order01_v001.json"\n\ndef get_path(obj: Any, dotted: str):\n    cur = obj\n    for part in dotted.split("."):\n        if isinstance(cur, dict) and part in cur:\n            cur = cur[part]\n        else:\n            raise KeyError(dotted)\n    return cur\n\ndef verify_baseline():\n    manifest = json.loads(BASELINE.read_text(encoding="utf-8"))\n    results = []\n    for check in manifest["checks"]:\n        path = ROOT / check["file"]\n        result = {"id":check["id"],"file":check["file"],"passed":False,"detail":""}\n        if not path.is_file():\n            result["detail"] = "missing file"\n            results.append(result)\n            continue\n        try:\n            obj = json.loads(path.read_text(encoding="utf-8"))\n            if check["type"] == "equals":\n                actual = get_path(obj, check["path"])\n                result["passed"] = actual == check["expected"]\n                result["detail"] = f"actual={actual!r} expected={check[\'expected\']!r}"\n            elif check["type"] == "all_field_equals":\n                rows = get_path(obj, check["list_path"])\n                vals = [r.get(check["field"]) for r in rows if isinstance(r, dict)]\n                result["passed"] = len(vals) == int(check["expected_count"]) and all(v == check["expected"] for v in vals)\n                result["detail"] = f"count={len(vals)} values={vals}"\n        except Exception as exc:\n            result["detail"] = f"{type(exc).__name__}: {exc}"\n        results.append(result)\n    return all(r["passed"] for r in results), results\n\ndef stage_status(stage):\n    req = [(p,(ROOT/p).exists()) for p in stage.requires]\n    prod = [(p,(ROOT/p).exists()) for p in stage.produces]\n    script_exists = None if stage.script is None else (ROOT/stage.script).is_file()\n    return {\n        "ready": all(ok for _,ok in req) and (script_exists is not False),\n        "complete": bool(prod) and all(ok for _,ok in prod),\n        "script_exists": script_exists,\n        "requirements": req,\n        "products": prod,\n        "guards": {\n            "network_access": stage.network_access,\n            "science_pixels_read": stage.science_pixels_read,\n            "non_science_pixels_read": stage.non_science_pixels_read,\n            "transient_detector_rerun": stage.transient_detector_rerun,\n            "candidate_state_mutation": stage.candidate_state_mutation,\n        }\n    }\n\ndef cmd_status(_args):\n    print("Transient automation v0.0.1 — Order01 registry status\\n")\n    for stage in ORDER01_STAGES:\n        s = stage_status(stage)\n        state = "COMPLETE" if s["complete"] else "READY" if s["ready"] else "BLOCKED"\n        print(f"{stage.stage_id:38} {state}")\n        if stage.script and s["script_exists"] is False:\n            print(f"  missing script: {stage.script}")\n        for p,ok in s["requirements"]:\n            if not ok: print(f"  missing requirement: {p}")\n        for p,ok in s["products"]:\n            if not ok: print(f"  missing product: {p}")\n\ndef cmd_verify(_args):\n    ok, results = verify_baseline()\n    print("ORDER01 FROZEN BASELINE VERIFICATION\\n")\n    for r in results:\n        print(f"[{\'PASS\' if r[\'passed\'] else \'FAIL\'}] {r[\'id\']}")\n        print(f"       {r[\'detail\']}")\n    print("\\nBASELINE STATUS:", "PASS" if ok else "FAIL")\n    STATE.append("baseline_verification", {"passed":ok,"checks":results})\n    STATE.write_snapshot({"baseline_passed":ok,"checks":results})\n    return 0 if ok else 2\n\ndef cmd_plan(_args):\n    print("SAFE AUTOMATION PLAN\\n")\n    for stage in ORDER01_STAGES:\n        s = stage_status(stage)\n        action = "VERIFY_EXISTING_OUTPUT" if s["complete"] else "ELIGIBLE_FOR_EXECUTION" if s["ready"] else "BLOCKED"\n        print(f"{stage.stage_id:38} {action}")\n    print("\\nNo stage was executed.")\n\ndef cmd_run(args):\n    stages = by_id()\n    stage = stages.get(args.stage)\n    if stage is None:\n        print(f"Unknown stage: {args.stage}", file=sys.stderr); return 2\n    s = stage_status(stage)\n    if stage.script is None:\n        print("Frozen artifact only; no executable script registered."); return 2\n    if not s["ready"]:\n        print("Stage is not ready; run `status`."); return 2\n    if s["complete"] and not args.force:\n        print("Stage already complete. No execution performed."); return 0\n    if stage.network_access and not args.allow_network:\n        print("REFUSED: --allow-network required."); return 3\n    if stage.candidate_state_mutation and not args.allow_state_mutation:\n        print("REFUSED: --allow-state-mutation required."); return 3\n    if stage.transient_detector_rerun and not args.allow_detector_rerun:\n        print("REFUSED: --allow-detector-rerun required."); return 3\n    cmd = [sys.executable, str(ROOT/stage.script)]\n    print("EXECUTING:", " ".join(cmd))\n    print("Declared guards:", json.dumps(s["guards"], sort_keys=True))\n    STATE.append("stage_start", {"stage_id":stage.stage_id,"command":cmd,"declared_guards":s["guards"]})\n    proc = subprocess.run(cmd, cwd=ROOT)\n    STATE.append("stage_end", {"stage_id":stage.stage_id,"returncode":proc.returncode})\n    return proc.returncode\n\ndef build_parser():\n    p = argparse.ArgumentParser()\n    sub = p.add_subparsers(dest="cmd", required=True)\n    s=sub.add_parser("status"); s.set_defaults(func=cmd_status)\n    s=sub.add_parser("verify-baseline"); s.set_defaults(func=cmd_verify)\n    s=sub.add_parser("plan"); s.set_defaults(func=cmd_plan)\n    s=sub.add_parser("run")\n    s.add_argument("--stage", required=True)\n    s.add_argument("--force", action="store_true")\n    s.add_argument("--allow-network", action="store_true")\n    s.add_argument("--allow-state-mutation", action="store_true")\n    s.add_argument("--allow-detector-rerun", action="store_true")\n    s.set_defaults(func=cmd_run)\n    return p\n\ndef main():\n    args=build_parser().parse_args()\n    return int(args.func(args) or 0)\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n', '__init__.py': '__version__ = "0.0.1"\\n', 'stages/__init__.py': '', 'README_AUTOMATION_V001.md': '# Transient automation foundation v0.0.1\n\nThis first layer is conservative: it verifies the current frozen Order01 state before executing anything.\n\nFrom the project root:\n\n```powershell\n& ".\\.venv\\Scripts\\python.exe" -m automation.runner verify-baseline\n& ".\\.venv\\Scripts\\python.exe" -m automation.runner status\n& ".\\.venv\\Scripts\\python.exe" -m automation.runner plan\n```\n\nExpected first milestone:\n\n```text\nBASELINE STATUS: PASS\n```\n\nIf baseline verification fails, do not force anything. The failure tells us which filename/schema assumption needs correcting.\n\nAfter the baseline passes, the next automation milestone is:\n- post-run guard extraction,\n- dependency traversal / run-next,\n- retries for network/cache stages,\n- opportunity queue with actual exposure-overlap gating,\n- whole-tile/whole-plate prevalence,\n- migration of the remaining survey workload.\n'}

def main():
    print("="*112)
    print("TRANSIENT / VILLARROEL AUTOMATION BOOTSTRAP v0.0.1")
    print("="*112)
    print("NO NETWORK ACCESS.")
    print("SCIENCE PIXELS ARE NOT READ.")
    print("Frozen transient detector is NOT rerun.")
    print("No existing result is modified.")
    print("No candidate state is changed.\n")

    if AUTO.exists() and any(AUTO.iterdir()):
        print(f"REFUSED: automation directory already exists and is non-empty: {AUTO}")
        return 2

    AUTO.mkdir(parents=True, exist_ok=True)
    (AUTO/"state").mkdir(parents=True, exist_ok=True)
    (AUTO/"stages").mkdir(parents=True, exist_ok=True)

    for rel, content in FILES.items():
        p = AUTO / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        if p.exists():
            raise RuntimeError(f"Refusing to overwrite existing file: {p}")
        p.write_text(content, encoding="utf-8")

    print("Created:")
    for p in sorted(AUTO.rglob("*")):
        if p.is_file():
            print("  " + str(p.relative_to(ROOT)))

    print("\nNext commands:")
    print(r'  & ".\.venv\Scripts\python.exe" -m automation.runner verify-baseline')
    print(r'  & ".\.venv\Scripts\python.exe" -m automation.runner status')
    print(r'  & ".\.venv\Scripts\python.exe" -m automation.runner plan')
    print("\nNo science was executed.")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
